// SystemServiceHandler is an implementation of the zitadel.system.v1.SystemService service.
type SystemServiceHandler interface {
	// Indicates if ZITADEL is running.
	// It respondes as soon as ZITADEL started
	Healthz(context.Context, *connect.Request[system.HealthzRequest]) (*connect.Response[system.HealthzResponse], error)
	// Returns a list of ZITADEL instances
	//
	// Deprecated: Use [ListInstances](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-list-instances.api.mdx) instead to list instances
	ListInstances(context.Context, *connect.Request[system.ListInstancesRequest]) (*connect.Response[system.ListInstancesResponse], error)
	// Returns the detail of an instance
	//
	// Deprecated: Use [GetInstance](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-get-instance.api.mdx) instead to get the details of the instance in context
	GetInstance(context.Context, *connect.Request[system.GetInstanceRequest]) (*connect.Response[system.GetInstanceResponse], error)
	// Deprecated: Use CreateInstance instead
	// Creates a new instance with all needed setup data
	// This might take some time
	AddInstance(context.Context, *connect.Request[system.AddInstanceRequest]) (*connect.Response[system.AddInstanceResponse], error)
	// Updates name of an existing instance
	//
	// Deprecated: Use [UpdateInstance](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-update-instance.api.mdx) instead to update the name of the instance in context
	UpdateInstance(context.Context, *connect.Request[system.UpdateInstanceRequest]) (*connect.Response[system.UpdateInstanceResponse], error)
	// Creates a new instance with all needed setup data
	// This might take some time
	CreateInstance(context.Context, *connect.Request[system.CreateInstanceRequest]) (*connect.Response[system.CreateInstanceResponse], error)
	// Removes an instance
	// This might take some time
	//
	// Deprecated: Use [DeleteInstance](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-delete-instance.api.mdx) instead to delete an instance
	RemoveInstance(context.Context, *connect.Request[system.RemoveInstanceRequest]) (*connect.Response[system.RemoveInstanceResponse], error)
	// Returns all instance members matching the request
	// all queries need to match (ANDed)
	// Deprecated: Use the Admin APIs ListIAMMembers instead
	ListIAMMembers(context.Context, *connect.Request[system.ListIAMMembersRequest]) (*connect.Response[system.ListIAMMembersResponse], error)
	// Checks if a domain exists
	//
	// Deprecated: Use [ListCustomDomains](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-list-custom-domains.api.mdx) instead to check existence of an instance
	ExistsDomain(context.Context, *connect.Request[system.ExistsDomainRequest]) (*connect.Response[system.ExistsDomainResponse], error)
	// List Domains
	//
	// Deprecated: use [instance service v2 ListCustomDomains](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-list-custom-domains.api.mdx) instead.
	//
	// Returns the custom domains of an instance.
	ListDomains(context.Context, *connect.Request[system.ListDomainsRequest]) (*connect.Response[system.ListDomainsResponse], error)
	// Adds a domain to an instance
	//
	// Deprecated: Use [AddCustomDomain](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-add-custom-domain.api.mdx) instead to add a custom domain to the instance in context
	AddDomain(context.Context, *connect.Request[system.AddDomainRequest]) (*connect.Response[system.AddDomainResponse], error)
	// Removes the domain of an instance
	//
	// Deprecated: Use [RemoveDomain](apis/resources/instance_service_v2/zitadel-instance-v-2-instance-service-remove-custom-domain.api.mdx) instead to remove a custom domain from the instance in context
	RemoveDomain(context.Context, *connect.Request[system.RemoveDomainRequest]) (*connect.Response[system.RemoveDomainResponse], error)
	// Sets the primary domain of an instance
	SetPrimaryDomain(context.Context, *connect.Request[system.SetPrimaryDomainRequest]) (*connect.Response[system.SetPrimaryDomainResponse], error)
	// Returns all stored read models of ZITADEL
	// views are used for search optimisation and optimise request latencies
	// they represent the delta of the event happend on the objects
	ListViews(context.Context, *connect.Request[system.ListViewsRequest]) (*connect.Response[system.ListViewsResponse], error)
	// Truncates the delta of the change stream
	// be carefull with this function because ZITADEL has to
	// recompute the deltas after they got cleared.
	// Search requests will return wrong results until all deltas are recomputed
	ClearView(context.Context, *connect.Request[system.ClearViewRequest]) (*connect.Response[system.ClearViewResponse], error)
	// Returns event descriptions which cannot be processed.
	// It's possible that some events need some retries.
	// For example if the SMTP-API wasn't able to send an email at the first time
	ListFailedEvents(context.Context, *connect.Request[system.ListFailedEventsRequest]) (*connect.Response[system.ListFailedEventsResponse], error)
	// Deletes the event from failed events view.
	// the event is not removed from the change stream
	// This call is usefull if the system was able to process the event later.
	// e.g. if the second try of sending an email was successful. the first try produced a
	// failed event. You can find out if it worked on the `failure_count`
	RemoveFailedEvent(context.Context, *connect.Request[system.RemoveFailedEventRequest]) (*connect.Response[system.RemoveFailedEventResponse], error)
	// Creates a new quota
	// Returns an error if the quota already exists for the specified unit
	// Deprecated: use SetQuota instead
	AddQuota(context.Context, *connect.Request[system.AddQuotaRequest]) (*connect.Response[system.AddQuotaResponse], error)
	// Sets quota configuration properties
	// Creates a new quota if it doesn't exist for the specified unit
	SetQuota(context.Context, *connect.Request[system.SetQuotaRequest]) (*connect.Response[system.SetQuotaResponse], error)
	// Removes a quota
	RemoveQuota(context.Context, *connect.Request[system.RemoveQuotaRequest]) (*connect.Response[system.RemoveQuotaResponse], error)
	// Set a feature flag on an instance
	SetInstanceFeature(context.Context, *connect.Request[system.SetInstanceFeatureRequest]) (*connect.Response[system.SetInstanceFeatureResponse], error)
	// Sets instance level limits
	SetLimits(context.Context, *connect.Request[system.SetLimitsRequest]) (*connect.Response[system.SetLimitsResponse], error)
	// Sets many instance level limits
	BulkSetLimits(context.Context, *connect.Request[system.BulkSetLimitsRequest]) (*connect.Response[system.BulkSetLimitsResponse], error)
	// Resets instance level limits
	ResetLimits(context.Context, *connect.Request[system.ResetLimitsRequest]) (*connect.Response[system.ResetLimitsResponse], error)
}

